const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry - Major reservoirs on Narmada River in central India
  // Indirasagar Reservoir (22.3°N, 76.5°E) and Sardar Sarovar Dam (21.8°N, 73.7°E)
  const reservoir1 = ee.Geometry.Point([76.5, 22.3]).buffer(5000);
  const reservoir2 = ee.Geometry.Point([73.7, 21.8]).buffer(5000);
  const reservoirArea = ee.Geometry.MultiPoint([[76.5, 22.3], [73.7, 21.8]]).buffer(5000);

  // 2. Date ranges (exact dates ±1 day)
  const date2023_start = '2023-02-09';
  const date2023_end = '2023-02-11';
  const date2025_start = '2025-01-29';
  const date2025_end = '2025-01-31';

  // Function to get Sentinel-2 imagery
  function getS2Image(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(reservoirArea)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
      .sort('CLOUDY_PIXEL_PERCENTAGE')
      .first();
  }

  // 3. Get images for both dates
  const img2023 = getS2Image(date2023_start, date2023_end);
  const img2025 = getS2Image(date2025_start, date2025_end);

  // Check if images exist
  const img2023_exists = img2023.getInfo() !== null;
  const img2025_exists = img2025.getInfo() !== null;

  print(`2023 Image exists: ${img2023_exists}`);
  print(`2025 Image exists: ${img2025_exists}`);

  if (!img2023_exists || !img2025_exists) {
    print("<answer>C1</answer>");
    return;
  }

  // Function to detect floating solar panels
  function detectSolarPanels(image) {
    // Cloud masking using QA60 band
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    const maskedImage = image.updateMask(mask);

    // NDWI to identify water (floating solar panels are on water)
    const ndwi = maskedImage.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Solar panel signature: high reflectance in visible and NIR
    const brightness = maskedImage.select(['B4', 'B3', 'B2']).reduce('mean'); // Red, Green, Blue mean
    const nir = maskedImage.select('B8');

    // Panel detection: bright AND on water (NDWI > 0) AND high NIR reflectance
    const waterMask = ndwi.gt(0.1); // Water areas
    const brightMask = brightness.gt(0.25); // Bright surfaces
    const nirMask = nir.gt(0.3); // High NIR reflectance (solar panels reflect NIR well)

    // Combine masks - looking for bright objects on water
    const panelMask = waterMask.and(brightMask).and(nirMask);

    return panelMask.selfMask();
  }

  // 4. Process both images
  const panels2023 = detectSolarPanels(img2023);
  const panels2025 = detectSolarPanels(img2025);

  // 5. Count pixels in each reservoir area
  const reducer = ee.Reducer.count();
  const scale = 1000; // Use 1000m scale for efficiency

  const count2023_res1 = panels2023.reduceRegion({
    reducer: reducer,
    geometry: reservoir1,
    scale: scale,
    maxPixels: 1e9
  }).get('NDWI');

  const count2023_res2 = panels2023.reduceRegion({
    reducer: reducer,
    geometry: reservoir2,
    scale: scale,
    maxPixels: 1e9
  }).get('NDWI');

  const count2025_res1 = panels2025.reduceRegion({
    reducer: reducer,
    geometry: reservoir1,
    scale: scale,
    maxPixels: 1e9
  }).get('NDWI');

  const count2025_res2 = panels2025.reduceRegion({
    reducer: reducer,
    geometry: reservoir2,
    scale: scale,
    maxPixels: 1e9
  }).get('NDWI');

  // Get values
  const c2023_r1 = ee.Number(count2023_res1).getInfo();
  const c2023_r2 = ee.Number(count2023_res2).getInfo();
  const c2025_r1 = ee.Number(count2025_res1).getInfo();
  const c2025_r2 = ee.Number(count2025_res2).getInfo();

  const total2023 = c2023_r1 + c2023_r2;
  const total2025 = c2025_r1 + c2025_r2;

  print(`2023-02-10 Panel pixels: ${total2023} (R1: ${c2023_r1}, R2: ${c2023_r2})`);
  print(`2025-01-30 Panel pixels: ${total2025} (R1: ${c2025_r1}, R2: ${c2025_r2})`);

  // 6. Validation and answer
  if (total2023 === null || total2025 === null || 
      isNaN(total2023) || isNaN(total2025)) {
    print("<answer>C3</answer>");
  } else if (total2023 === 0 && total2025 === 0) {
    print("<answer>C2</answer>");
  } else if (total2023 > total2025) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
